-- 3. Each card's Douyin count is its November reading.
UPDATE "creator_cards" AS c
SET "douyin_followers" = k."followers"
FROM "creator_follower_checks" AS k
WHERE k."card_id" = c."id" AND k."platform" = 'douyin' AND k."month" = '2026-11-01'::date AND k."status" = 'ok'
  AND c."douyin_followers" IS NULL;
